// Claudeのtool_use出力(input)は既にパース済みオブジェクトなので、JSON.parseは不要
const content = $input.first().json.content ?? [];
const toolUse = content.find(b => b.type === 'tool_use' && b.name === 'submit_article');
if (!toolUse) {
  throw new Error('Claude応答にtool_useブロックが見つかりませんでした: ' + JSON.stringify(content).slice(0, 300));
}
const parsed = toolUse.input;
return [{
  json: {
    title: parsed.title,
    meta_description: parsed.meta_description,
    body_md: parsed.body_md,
    tags: parsed.tags ?? [],
    status: 'draft',
    images: parsed.images ?? [],
    eyecatch_prompt: parsed.eyecatch_prompt ?? ''
  }
}];

// 手動実行(入力例)・サブワークフロー実行トリガーのどちらから来ても、
// main_keyword/target_reader/differentiationを持つitemをそのまま次に渡す
return $input.all();

// Geminiのレスポンス(candidates[0].content.parts[].text)から競合記事リサーチ要約を取り出す
const item = $input.first().json;
const parts = item.candidates?.[0]?.content?.parts ?? [];
const competitor_research = parts.map(p => p.text ?? '').join('\n').trim() || '（競合記事リサーチを取得できませんでした。Gemini credentialの設定を確認してください）';
return [{ json: { competitor_research } }];

// レスポンス整形で得たimages[](本文用・最大3枚)を、itemに展開する。
// アイキャッチは独立したチェーン(アイキャッチプロンプト作成〜アイキャッチをアップロード)で
// NG時の再生成ループつきで別途処理されるため、ここでは本文用画像のみを扱う。
// ブランドの世界観（配色・雰囲気）はここで固定文言として必ず付与し、
// 記事ごとにばらつかないようにする(ユーザー要望: 全生成画像で世界観を統一する)。
//
// このノードの直接の上流(グラフ上の$input)はアイキャッチをアップロードであり
// (本文用画像の生成をアイキャッチ確定後に開始させるための順序制御)、
// レスポンス整形ではないため、記事データは名前参照で取得する。
const STYLE_PREFIX = "ゴールド×バイオレットのグラデーションを基調にした、上品で神秘的な占星術テイストのイラスト。過度に装飾せずシンプルで洗練されたデザイン。星・惑星・幾何学模様のモチーフを控えめに使用。写実的すぎないフラットまたはソフトなグラデーション調のイラストスタイル。文字を含める場合は日本語として正確に読みやすく描画すること。横長(16:9〜3:2程度)の構図。";

const article = $('レスポンス整形').first().json;
const results = [];

// 本文用画像(最大3枚、念のためここでも上限を強制する)
const images = (Array.isArray(article.images) ? article.images : []).slice(0, 3);
for (const img of images) {
  results.push({
    json: {
      marker: img.marker,
      alt_text: img.alt_text,
      is_eyecatch: false,
      image_prompt: `${STYLE_PREFIX}\n\n描く内容: ${img.content_prompt}`
    }
  });
}

return results;

// Gemini品質チェックの結果を、後段の集約処理と共通のフォーマットに正規化する。
// (このノードではアップロードは行わない。全画像のレビューが確定してから最後にまとめてアップロードする)
const qaJson = $json;
const qaText = (qaJson?.candidates?.[0]?.content?.parts ?? []).map(p => p.text || '').join('');
const isNG = qaText.includes('NG');

const orig = $('画像プロンプトを展開').item.json;
const b64 = $('OpenAIで画像生成').item.json.data?.[0]?.b64_json ?? null;

// OpenAI側がエラーを返した場合(b64が無い)は、Geminiのテキストに「NG」が含まれていなくても
// 明示的に失敗扱いにする(空文字列には「NG」が含まれないため、素通りしてしまうのを防ぐ)。
if (!b64) {
  return { json: { item_key: orig.marker, image_type: 'body', ok: false, alt_text: orig.alt_text, b64: null, error_reason: '画像生成自体に失敗しました(OpenAI APIエラー)', image_prompt: orig.image_prompt } };
}

return { json: { item_key: orig.marker, image_type: 'body', ok: !isNG, alt_text: orig.alt_text, b64, error_reason: isNG ? qaText : null, image_prompt: orig.image_prompt } };

// アップロード結果(HTTP Requestのレスポンスでjsonが上書きされ、item_key等は失われている)を、
// 同じ順序で並んでいるはずの「最終Binary変換」の出力(item_key/alt_text/image_typeを保持)と
// 位置(index)で突き合わせて対応づける(アイキャッチ・本文画像すべてをこの1つのアップロード工程で処理する)。
const article = $('レスポンス整形').first().json;
let body = article.body_md || '';
let eyecatchUrl = null;

const uploadResults = $input.all();
const itemSource = $('最終Binary変換').all();

for (let i = 0; i < uploadResults.length; i++) {
  const meta = itemSource[i]?.json;
  if (!meta) continue;
  const uploadJson = uploadResults[i]?.json || {};
  const url = uploadJson.url;

  if (meta.image_type === 'eyecatch') {
    if (url) eyecatchUrl = url;
    continue;
  }

  if (url) {
    body = body.split(meta.item_key).join(`![${meta.alt_text}](${url})`);
  } else {
    body = body.split(meta.item_key).join('');
  }
}
// 念のため残った[IMAGE_N]パターンも取り除く
body = body.replace(/\[IMAGE_\d+\]/g, '');

const result = {
  title: article.title,
  meta_description: article.meta_description,
  body_md: body,
  tags: article.tags,
  status: 'draft'
};
if (eyecatchUrl) result.eyecatch_url = eyecatchUrl;

return [{ json: result }];

// アイキャッチ専用のプロンプトを組み立てる(本文用画像とは切り離して単独で扱う)。
// 独立チェーンにしているのは、NG時に再生成ループさせるため
// (本文用画像は最大3枚・リトライなしのまま、これまで通りNGなら削除するだけ)。
const STYLE_PREFIX = "ゴールド×バイオレットのグラデーションを基調にした、上品で神秘的な占星術テイストのイラスト。過度に装飾せずシンプルで洗練されたデザイン。星・惑星・幾何学模様のモチーフを控えめに使用。写実的すぎないフラットまたはソフトなグラデーション調のイラストスタイル。文字を含める場合は日本語として正確に読みやすく描画すること。横長(16:9〜3:2程度)の構図。";

const article = $input.first().json;
const basePrompt = `${STYLE_PREFIX}\n\n描く内容: ${article.eyecatch_prompt}\n\nこの画像には記事タイトル「${article.title}」を、読みやすい日本語のテキストとして画像内に大きく配置すること（タイトルの描画は必須）。`;

return [{
  json: {
    alt_text: article.title,
    image_prompt: basePrompt,
    attempt: 1
  }
}];

// アイキャッチプロンプト作成(初回)またはIFノードのループバック(再試行時)、
// どちらから来ても同じ形({image_prompt, attempt, alt_text})を持つ。
// アイキャッチ画像生成の直前にある、名前参照で安定して辿れる合流ポイントとして機能する
// (OpenAI呼び出し後はjsonが上書きされてattempt等が失われるため、
// このノードを経由して$('アイキャッチ生成準備')から復元できるようにしている)。
return [{ json: $input.first().json }];

// Gemini品質チェックの結果を見て、再試行するか確定するかを判定する。
// 最大MAX_ATTEMPTS回まで試し、それでもNGなら人間のDiscordレビューに回す
// (b64は常に保持しておき、NGのまま確定してもレビュー用に表示できるようにする)。
const MAX_ATTEMPTS = 3;

const qaJson = $input.first().json;
const qaText = (qaJson?.candidates?.[0]?.content?.parts ?? []).map(p => p.text || '').join('');
const isNG = qaText.includes('NG');

const prep = $('アイキャッチ生成準備').first().json;
const attempt = prep.attempt || 1;
const b64 = $('アイキャッチ画像生成').first().json.data?.[0]?.b64_json ?? null;

if (!isNG) {
  return [{ json: { retry: false, item_key: 'eyecatch', image_type: 'eyecatch', ok: true, alt_text: prep.alt_text, b64, error_reason: null, image_prompt: prep.image_prompt } }];
}

if (attempt >= MAX_ATTEMPTS) {
  return [{ json: { retry: false, item_key: 'eyecatch', image_type: 'eyecatch', ok: false, alt_text: prep.alt_text, b64, error_reason: qaText || '3回試行しても改善しませんでした', image_prompt: prep.image_prompt } }];
}

// 再試行: 手足・指の本数や身体バランスに関する補足指示を追記して精度を上げる
const correctivePrompt = `${prep.image_prompt}\n\n(${attempt}回目の生成で不自然な点が見つかったため再生成中。特に手と指は必ず片手5本ずつの自然な形で描き、体のパーツ数・比率が写実的に正しくなるよう細心の注意を払うこと。)`;

return [{
  json: {
    retry: true,
    image_prompt: correctivePrompt,
    attempt: attempt + 1,
    alt_text: prep.alt_text
  }
}];

// アイキャッチ(名前参照、常に1件確定済み)と本文画像(直接の入力、0〜3件)を1つの配列にまとめる。
const bodyImages = $input.all().map(i => i.json);
const eyecatch = $('アイキャッチ確定').first().json;
return [{ json: { images: [eyecatch, ...bodyImages] } }];

const agg = $input.first().json;
const batchId = `batch_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
return [{ json: { batchId, images: agg.images } }];

// Discord botから届いた判定結果を、レビュー前の全画像配列にマージする。
// 承認(approve)はNGフラグのまま使う(ok:trueにする)。修正/やり直しはneeds_regenを立てて後段の再生成対象にする。
const allImages = $('Discordレビュー用に整形').first().json.images;
const decisions = $json.decisions ?? [];
const decisionByKey = Object.fromEntries(decisions.map(d => [d.itemKey, d]));

const updated = allImages.map(img => {
  const decision = decisionByKey[img.item_key];
  if (!decision) return img;
  if (decision.action === 'approve') return { ...img, ok: true };
  return { ...img, needs_regen: true, correction_text: decision.action === 'revise' ? decision.correctionText : null };
});

return [{ json: { images: updated } }];

const agg = $input.first().json;
const toRegen = agg.images.filter(i => i.needs_regen);
return toRegen.map(i => ({
  json: {
    item_key: i.item_key,
    image_type: i.image_type,
    alt_text: i.alt_text,
    image_prompt: i.correction_text ? `${i.image_prompt}\n\n(追加の修正指示: ${i.correction_text})` : i.image_prompt,
  }
}));

const geminiJson = $json;
const qaText = (geminiJson?.candidates?.[0]?.content?.parts ?? []).map(p => p.text || '').join('');
const isNG = qaText.includes('NG');

const orig = $('再生成対象を展開').item.json;
const b64 = $('再生成:OpenAIで画像生成').item.json.data?.[0]?.b64_json ?? null;

if (!b64) {
  return { json: { item_key: orig.item_key, image_type: orig.image_type, ok: false, alt_text: orig.alt_text, b64: null, error_reason: '画像生成自体に失敗しました(OpenAI APIエラー)', image_prompt: orig.image_prompt } };
}

return { json: { item_key: orig.item_key, image_type: orig.image_type, ok: !isNG, alt_text: orig.alt_text, b64, error_reason: isNG ? qaText : null, image_prompt: orig.image_prompt } };

const regenerated = $input.all().map(i => i.json);
const allBefore = $('レビュー結果を反映').first().json.images;
const regenByKey = Object.fromEntries(regenerated.map(r => [r.item_key, r]));
const merged = allBefore.map(img => regenByKey[img.item_key] ?? img);
return [{ json: { images: merged } }];

const item = $json;
if (!item.b64) {
  return { json: { item_key: item.item_key, image_type: item.image_type, alt_text: item.alt_text, failed: true } };
}
const buffer = Buffer.from(item.b64, 'base64');
const fileName = `${(item.item_key ?? 'image').replace(/[^a-zA-Z0-9]/g, '')}.png`;
const binary = await this.helpers.prepareBinaryData(buffer, fileName, 'image/png');
return { json: { item_key: item.item_key, image_type: item.image_type, alt_text: item.alt_text, failed: false }, binary: { file: binary } };
